mapper.update:
UPDATE user_resumes SET version=#{row.version},markdown_text=#{row.markdownText},source_kind=#{row.sourceKind},
    current_object_id=#{row.currentObjectId},content_sha256=#{row.contentSha256},updated_at=#{row.updatedAt}
WHERE user_id=#{row.userId} AND version=#{expected}

UPDATE resume_objects SET status='DELETING',operation_token=#{token},lease_expires_at=#{deadline},updated_at=#{now}
WHERE user_id=#{owner} AND id=#{id} AND status!='UPLOADING'
    AND NOT EXISTS(SELECT 1 FROM user_resumes r WHERE r.user_id=#{owner} AND r.current_object_id=#{id})
